effect.frag.content:
int sourceIndex = 0;
uniform float u_amount;
const float TAU = 6.28318530718;
vec4 sourceAt(vec2 uv) {
  if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) return vec4(0.0);
  return imageAt(sourceIndex, uv);
}
void main() {
  vec2 grid = vec2(10.0, 10.0), cell = floor(v_uv * grid);
  sourceIndex = int(cell.x + cell.y * grid.x);
  vec2 p = fract(v_uv * grid) - 0.5;
  float a = TAU * u_progress;
  float cx = cos(a), cy = cos(a * 2.0);
  float perspective = 1.0 + sin(a) * p.x * u_amount * 0.5;
  if (abs(cx) < 0.0001 || abs(cy) < 0.0001) { fragColor = vec4(0.0); return; }
  vec2 uv = p * perspective / vec2(cx, cy) + 0.5;
  bool inside = all(greaterThanEqual(uv, vec2(0.0))) && all(lessThanEqual(uv, vec2(1.0)));
  fragColor = inside ? sourceAt(inputCount > 1 ? uv : (cell + uv) / grid) : vec4(0.0);
}
